using System;
using System.Text.Json;
string json = """{"Title":"Read","Minutes":15}""";
try
{
    Goal? goal = JsonSerializer.Deserialize<Goal>(json);
    if (goal is null || string.IsNullOrWhiteSpace(goal.Title) || goal.Minutes < 0)
        Console.WriteLine("Rejected");
    else
        Console.WriteLine("Accepted: " + JsonSerializer.Serialize(goal));
}
catch (JsonException) { Console.WriteLine("Invalid JSON"); }
public class Goal
