    let mut context = Context::from_waker(Waker::noop());
    match future.as_mut().poll(&mut context) {
        Poll::Ready(value) => println!("{value}"),
        Poll::Pending => panic!("ready future unexpectedly pending"),
    }
}

macro_rules! twice {
    ($value:expr) => {{ let value = $value; value + value }};
}
fn main() {
    let mut calls = 0;
    let answer = twice!({ calls += 1; 3 });
    println!("{answer} {calls}");
}

macro_rules! twice {
    ($value:expr) => {{ ($value) + ($value) }};
}
fn main() {
    let mut calls = 0;
    let answer = twice!({ calls += 1; 3 });
    println!("{answer} {calls}");
}

